def subtract(a, b):
    # Filter out empty intervals and sort
    a_intervals = sorted([interval for interval in a if interval[0] < interval[1]])
    b_intervals = sorted([interval for interval in b if interval[0] < interval[1]])

    if not a_intervals:
        return []

    # Merge overlapping intervals in b
    b_merged = []
    for start, end in b_intervals:
        if b_merged and start <= b_merged[-1][1]:
            b_merged[-1][1] = max(b_merged[-1][1], end)
        else:
            b_merged.append([start, end])

    # Subtract b from a
    result = []
    for a_start, a_end in a_intervals:
        current = a_start
        for b_start, b_end in b_merged:
            if b_end <= current:
                # b interval is completely before current position
                continue
            if b_start >= a_end:
                # b interval is completely after a interval
                break
            # Add the part before the b interval if it exists
            if current < b_start:
                result.append([current, b_start])
            # Move current to after the b interval
            current = max(current, b_end)
        # Add remaining part if any
        if current < a_end:
            result.append([current, a_end])

    # Merge adjacent intervals that touch
    if not result:
        return []

    merged = [result[0]]
    for start, end in result[1:]:
        if start == merged[-1][1]:
            merged[-1][1] = end
        else:
            merged.append([start, end])

    return merged

